// TestClient_Params sets every parameter it can to a value other than its zero value, and finds each in the request,
// under its name and written as the client must write it.
func TestClient_Params(t *testing.T) {
	t.Run("GetMe", func(t *testing.T) {
		t.Setenv("TOGGL_API_USERNAME", "user")
		t.Setenv("TOGGL_API_PASSWORD", "pass")

		var got *http.Request

		c, err := NewClient(WithHTTPClient(&http.Client{Transport: apitest.RoundTripFunc(
			func(r *http.Request) (*http.Response, error) {
				got = r

				return &http.Response{StatusCode: http.StatusTeapot, Header: http.Header{}, Body: http.NoBody, Request: r}, nil
			},
		)}))
		if err != nil {
			t.Fatal(err)
		}

		_, _ = c.GetMe(t.Context(), &GetMeParams{
			WithRelatedData: true,
		})

		if got == nil {
			t.Fatal("no request was sent")
		}

		if v := got.URL.Query().Get("with_related_data"); v != "true" {
			t.Errorf("query %s: got %q, want %q", "with_related_data", v, "true")
		}
	})
	t.Run("ListTimeEntries", func(t *testing.T) {
		t.Setenv("TOGGL_API_USERNAME", "user")
		t.Setenv("TOGGL_API_PASSWORD", "pass")

		var got *http.Request

		c, err := NewClient(WithHTTPClient(&http.Client{Transport: apitest.RoundTripFunc(
			func(r *http.Request) (*http.Response, error) {
				got = r

				return &http.Response{StatusCode: http.StatusTeapot, Header: http.Header{}, Body: http.NoBody, Request: r}, nil
			},
		)}))
		if err != nil {
			t.Fatal(err)
		}

		_, _ = c.ListTimeEntries(t.Context(), &ListTimeEntriesParams{
			Meta:           true,
			IncludeSharing: true,
		})

		if got == nil {
			t.Fatal("no request was sent")
		}

		if v := got.URL.Query().Get("meta"); v != "true" {
			t.Errorf("query %s: got %q, want %q", "meta", v, "true")
		}
		if v := got.URL.Query().Get("include_sharing"); v != "true" {
			t.Errorf("query %s: got %q, want %q", "include_sharing", v, "true")
		}
	})
}

func TestClient_Interactions(t *testing.T) {
	ctx := t.Context()
	t.Setenv("TOGGL_API_USERNAME", "user")
	t.Setenv("TOGGL_API_PASSWORD", "pass")

	last := &apitest.LastBody{Next: apitest.Replay(t, "../../api/interactions.json")}

	c, err := NewClient(WithHTTPClient(&http.Client{Transport: last}))
	if err != nil {
		t.Fatal(err)
	}

	if out, err := c.GetMe(ctx, &GetMeParams{}); err != nil {
		t.Fatalf("GetMe: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetMe", out, last.Body, jsonOpts)
	}

	if out, err := c.GetMe(ctx, &GetMeParams{
		WithRelatedData: true,
	}); err != nil {
		t.Fatalf("GetMe: %v", err)
	} else {
		apitest.DecodedAsSent(t, "GetMe", out, last.Body, jsonOpts)
	}

	if _, err := c.GetMe(ctx, &GetMeParams{
		WithRelatedData: true,
	}); err == nil {
		t.Fatal("GetMe: expected error")
	} else if _, ok := errors.AsType[*api.ErrorBody](err); !ok {
		t.Fatalf("GetMe: got: %T, want: *api.ErrorBody", err)
	}

	if out, err := c.ListTimeEntries(ctx, &ListTimeEntriesParams{
		StartDate: time.Date(2026, 10, 9, 15, 32, 44, 0, time.FixedZone("", 7200)),
		EndDate:   time.Date(2026, 10, 23, 15, 32, 44, 0, time.FixedZone("", 7200)),
	}); err != nil {
		t.Fatalf("ListTimeEntries: %v", err)
	} else {
		apitest.DecodedAsSent(t, "ListTimeEntries", out, last.Body, jsonOpts)
	}

	if _, err := c.StopTimeEntry(ctx, 2230580, 4598868048); err == nil {
		t.Fatal("StopTimeEntry: expected error")
	} else if _, ok := errors.AsType[*APIErrorString](err); !ok {
		t.Fatalf("StopTimeEntry: got: %T, want: *APIErrorString", err)
	}

	if out, err := c.UpdateTimeEntry(ctx, 2230580, 4606721930, TimeEntryUpdate{
		Stop: time.Date(2026, 10, 31, 17, 15, 53, 245516000, time.FixedZone("", 3600)),
	}); err != nil {
		t.Fatalf("UpdateTimeEntry: %v", err)
	} else {
		apitest.DecodedAsSent(t, "UpdateTimeEntry", out, last.Body, jsonOpts)
	}
}
